from tools.experiments.chapter07_consumers_peer.test_strength_current import *
def test_silence_status_and_marker_refresh_never_duplicate_native_nonsilenceable_listener():
 p=strength_package('strength_silence_refresh');p['buffs'].append({'id':'buff/peer/silence','kind':'buff','selection_flags':{'abnormal_flags':[7]}});p['abilities'][0]['activation']['on_start'] += [{'op':'apply_buff','target':t,'buff':'buff/peer/silence'} for t in [3,4,5]];s=create(p,STRENGTH);command(s,'all_on',3);command(s,'all_on',9);s.advance(17);capture(s,'strength_silence_refresh');assert all(len(derived(s,a))==1 for a in ['v1','v2','v3']);assert s.ctx.attributes.value('v1','atk')==540 and s.ctx.attributes.value('v2','atk')==774
def test_real_public_blocker_three_source_melee_packets_use_their_own_strength():
 p=strength_package('strength_packets');p['scenarioDraft']['parameters']={'deploy_capacity':1};p['scenarioDraft']['dependencies']=['unit/peer/blocker'];p['entities'].append({'id':'unit/peer/blocker','kind':'entity','tags':['player','ground'],'components':{'attributes':{'base':{'max_hp':90000,'atk':0,'def':31,'mres':17,'block_count':3}},'resources':{'hp':{'initial':90000,'capacity':90000,'role':'health'}},'selection_state':{'side':0,'motion':1,'category':1,'unit_type':1},'deployable':{'base_cost':0,'terrain':'ground','capacity':1,'refund_ratio':0},'lifecycle':{'policy':'policy/ark_lifecycle'},'spatial':{}}})
 for row in p['scenarioDraft']['initialEntities'][1:]:row['position']={'row':3,'col':2};row['route']={'motionMode':'WALK','startPosition':{'row':3,'col':2},'endPosition':{'row':3,'col':5},'checkpoints':[]}
 s=create(p,STRENGTH);s.submit({'action':'deploy','definition':'unit/peer/blocker','position':{'row':3,'col':2},'alias':'blocker'},at=0);command(s,'all_on',3);s.advance(16);capture(s,'three_native_melee_packets');hits=events(s,'damage.accepted');assert len(hits)==3
 bysource={e['payload']['source']:e['payload']['amount'] for e in hits};assert bysource=={s.session.world.resolve('v1'):509,s.session.world.resolve('v2'):743,s.session.world.resolve('v3'):269}
 assert all(e['payload']['target']==s.session.world.resolve('blocker') for e in hits) and s.ctx.resources.current('blocker','hp')==90000-509-743-269
